 draw(){const c=this.canvas,g=this.gl,w=c.clientWidth,h=c.clientHeight;if(!w||!h)return;const d=Math.min(devicePixelRatio||1,1.5);if(c.width!==Math.round(w*d)||c.height!==Math.round(h*d)){c.width=Math.round(w*d);c.height=Math.round(h*d)}g.viewport(0,0,c.width,c.height);g.clearColor(.045,.08,.14,1);g.clear(g.COLOR_BUFFER_BIT|g.DEPTH_BUFFER_BIT);let view=mul(translate(0,0,-this.zoom),mul(rx(this.pitch),mul(ry(this.yaw),translate(-this.target[0],-this.target[1],-this.target[2]))));this.vp=mul(perspective(.65,w/h,.1,400),view);this.projections=[];let html='';
 for(const o of this.objects){const model=mul(translate(...o.pos),scale(...o.size));g.uniformMatrix4fv(this.mvp,false,new Float32Array(mul(this.vp,model)));g.uniform3fv(this.color,o.selected?[1,.72,.27]:o.color||colors.default);g.drawArrays(g.TRIANGLES,0,36);const p=point(this.vp,o.pos);if(p[2]<-1||p[2]>1)continue;const x=(p[0]+1)*w/2,y=(1-p[1])*h/2;let minX=w,maxX=0,minY=h,maxY=0;for(const a of [-1,1])for(const b of [-1,1])for(const d of [-1,1]){const q=point(this.vp,o.pos.map((v,i)=>v+[a,b,d][i]*o.size[i]/2));minX=Math.min(minX,(q[0]+1)*w/2);maxX=Math.max(maxX,(q[0]+1)*w/2);minY=Math.min(minY,(1-q[1])*h/2);maxY=Math.max(maxY,(1-q[1])*h/2)}this.projections.push({id:o.id,x,y,z:p[2],minX,maxX,minY,maxY});if(o.label&&x>0&&x<w&&y>0&&y<h)html+=`<span class="scene-label ${o.selected?'selected':''}" style="left:${x}px;top:${y}px">${escape(o.label)}</span>`;
 }this.labels.innerHTML=html;this.canvas.dataset.rendered='true';this.canvas.dataset.objects=String(this.objects.length);this.canvas.dataset.drawCount=String(+(this.canvas.dataset.drawCount||0)+1)}
 pick(x,y){const hits=this.projections.filter(p=>x>=p.minX-5&&x<=p.maxX+5&&y>=p.minY-4&&y<=p.maxY+4).sort((a,b)=>a.z-b.z);if(hits.length)this.onPick(hits[0].id)}
